mapper.update:
MERGE INTO TB_PROJECT T
USING DUAL
   ON (T.PROJ_IDX = #{projIdx})
WHEN MATCHED THEN
    UPDATE SET
           T.TITLE           = #{title}
         , T.CATEGORY        = #{category}
         , T.SUB_CATEGORY    = #{subCategory}
         , T.REGION          = #{region}
         , T.PLAN_STATUS     = #{planStatus}
         , T.WORK_TYPE       = #{workType}
         , T.DURATION_DAYS   = #{durationDays}
         , T.COST_MIN        = #{costMin}
         , T.COST_MAX        = #{costMax}
         , T.APPLY_COUNT     = #{applyCount}
         , T.SKILL_RAW       = #{skillRaw}
         , T.SUMMARY         = #{summary, jdbcType=CLOB}
         , T.POSTED_AT       = #{postedAt}
         , T.DEADLINE        = #{deadline}
         , T.LAST_CRAWLED_AT = SYSDATE
WHEN NOT MATCHED THEN
    INSERT (
           PROJ_IDX, TITLE, CATEGORY, SUB_CATEGORY, REGION
         , PLAN_STATUS, WORK_TYPE, DURATION_DAYS, COST_MIN, COST_MAX
         , APPLY_COUNT, SKILL_RAW, SUMMARY, POSTED_AT, DEADLINE
         , FIRST_CRAWLED_AT, LAST_CRAWLED_AT
    ) VALUES (
           #{projIdx}, #{title}, #{category}, #{subCategory}, #{region}
         , #{planStatus}, #{workType}, #{durationDays}, #{costMin}, #{costMax}
         , #{applyCount}, #{skillRaw}, #{summary, jdbcType=CLOB}, #{postedAt}, #{deadline}
         , SYSDATE, SYSDATE
    )
